language "EAL/3"

environment lab {
  require "site" == "bench"
}

tool runner {
  version "1"
}

evidence observation {
  tool runner
  kind test
  environment lab
  max_age 60
  input {"suite": "smoke", "args": [1, true, null]}
  require "passed" == true
}

assumption stable {
  statement "The measured configuration persists."
  environment lab
  validate observation
  valid_until "2027-01-01T00:00:00Z"
}

reasoning measured {
  method "structured/1"
  rationale "The bounded test result supports the stated test claim."
}

claim working {
  statement "The smoke test passes."
  environment lab
}

argument first = [evidence observation, assumptions stable] via measured => working

language "EAL/3"

environment lab {
  require "site" == "bench"
}

tool readings {
  version "1"
}

evidence trial {
  tool readings
  kind experiment
  environment lab
  max_age 60
  require "schema" == "EAL/typed-input/1"
}

reasoning difference {
  method "causal/1"
  rationale "Difference of means in the declared randomised experiment."
}

claim raised {
  statement "The treatment mean pressure exceeds control by at least 5 kPa."
  environment lab
  proposition {
    subject "pump-A"
    quantity "pressure"
    unit "kPa"
    scope "experiment-v1"
    valid_from "2026-09-23T10:00:00Z"
    valid_until "2026-09-23T11:00:00Z"
    query {"assignment": "randomised"}
    result "estimate" >= 5
  }
}

argument contrast = [evidence trial] via difference => raised binding trial

